function readInfinitySession() {
    if (typeof window === "undefined")
        return { runs: 0, remixes: 0, history: [] }
    try {
        const raw = window.sessionStorage.getItem(SESSION_KEY)
        const parsed = raw ? JSON.parse(raw) : null
        return {
            runs: Math.max(0, Number(parsed?.runs) || 0),
            remixes: Math.max(0, Number(parsed?.remixes) || 0),
            history: Array.isArray(parsed?.history)
                ? parsed.history
                      .filter((n) => Number.isFinite(Number(n)))
                      .map(Number)
                      .slice(-14)
                : [],
        }
    } catch {
        return { runs: 0, remixes: 0, history: [] }
    }
}
function writeInfinitySession(session) {
    if (typeof window === "undefined") return
    try {
        window.sessionStorage.setItem(SESSION_KEY, JSON.stringify(session))
    } catch {}
}
function noveltyNoise(id, salt) {
    const x = Math.sin((id + 1) * 12.9898 + (salt + 1) * 78.233) * 43758.5453
    return x - Math.floor(x)
}
function infinityChoices(current, history, played, salt, limit = 3) {
    const recent = history.slice(-7)
    const scored = GAMES.map((g) => {
        let score = noveltyNoise(g.id, salt) * 16
        if (!played.includes(g.id)) score += 72
        if (!recent.includes(g.id)) score += 38
        else score -= 120 - Math.max(0, recent.indexOf(g.id)) * 6
        if (current) {
            if (g.id === current.id) score -= 240
            if (g.family !== current.family) score += 46
            else score -= 18
            if (g.engine !== current.engine) score += 28
            else score -= 8
        }
        const familyRecent = recent
            .map((id) => GAMES.find((x) => x.id === id)?.family)
            .filter(Boolean)
        if (!familyRecent.includes(g.family)) score += 20
        return { g, score }
    }).sort((a, b) => b.score - a.score)
    return scored.slice(0, Math.max(1, limit)).map((x) => x.g)
}
function pickInfinityGame(current, history, played, salt) {
    const picks = infinityChoices(current, history, played, salt, 5)
    if (!picks.length) return GAMES[0]
    const index = Math.floor(
        noveltyNoise((current?.id || 0) + salt, salt + 91) *
            Math.min(3, picks.length)
    )
    return picks[Math.max(0, Math.min(picks.length - 1, index))]
}
