        if (typeof window === "undefined") return
        if (!audio.current) {
            audio.current = new Audio()
            audio.current.loop = true
            audio.current.preload = "auto"
        }
        const a = audio.current
        a.volume = clamp(volume, 0, 1)
        if (url && a.src !== url) a.src = url
        if (on && url) a.play().catch(() => {})
