function releaseEmotionSet(
    game,
    positiveFlags = false,
    count = MAX_VISIBLE_WORD_BUBBLES,
    sessionSeed = 0,
    reactionEpoch = 0,
    inputEntries = []
) {
    const family = game?.family || "Release"
    const baseOrder = [
        ...new Set([...(FAMILY_BUBBLES[family] || []), ...ALL_BUBBLES]),
    ]
    const profileId = releaseEmotionProfile(inputEntries).id
    const profileSalt = releaseReactionSalt(profileId)
    const gameId = Math.abs(Number(game?.id) || 0)
    const shuffleSeed =
        (Number(sessionSeed) || 0) ^
        Math.imul(gameId + 1, 0x45d9f3b) ^
        Math.imul(profileSalt + 1, 0x27d4eb2d)
    const order = [...baseOrder]
        .map((bubble, idx) => ({
            bubble,
            sortKey: releaseReactionSalt(
                `${family}:${bubble}:${shuffleSeed}:${idx}`
            ),
        }))
        .sort((a, b) => a.sortKey - b.sortKey)
        .map((item) => item.bubble)
    const start =
        (gameId + (Number(sessionSeed) || 0) + profileSalt) %
        Math.max(1, order.length)
    const occurrences = {}
    const usedTags = new Map()
    const usedSources = new Set()
    let previousTag = ""
    return Array.from({ length: Math.max(1, count) }, (_, i) => {
        const bubble = order[(start + i) % order.length]
        const occurrence = occurrences[bubble] || 0
        occurrences[bubble] = occurrence + 1
        const positive = Array.isArray(positiveFlags)
            ? !!positiveFlags[i]
            : !!positiveFlags
        const phase = positive ? "positive" : "negative"
        const bank = RELEASE_PHASE_EMOTIONS[phase][bubble] || [1]
        const base = Math.abs(
            Math.imul(gameId + 17, 31) +
                Math.imul(Number(sessionSeed) || 0, 7) +
                Math.imul(profileSalt, 3) +
                Math.imul(i + 1, 13) +
                Math.imul(occurrence + 1, 19) +
                Math.imul(Math.max(0, reactionEpoch) + 1, 23)
        )
        let chosenMood = bank[base % bank.length]
        let chosenTag = releaseReactionTag(phase, bubble, chosenMood)
        let chosenSrc = emotionSrc(bubble, chosenMood)
        let bestScore = Number.POSITIVE_INFINITY
        for (let offset = 0; offset < bank.length; offset++) {
            const mood = bank[(base + offset) % bank.length]
            const tag = releaseReactionTag(phase, bubble, mood)
            const candidateSrc = emotionSrc(bubble, mood)
            const used = usedTags.get(tag) || 0
            const exactRepeatPenalty = usedSources.has(candidateSrc) ? 10000 : 0
            const score =
                exactRepeatPenalty +
                used * 100 +
                (tag === previousTag ? 45 : 0) +
                offset +
                ((reactionEpoch + i + offset) % 3) * 0.01
            if (score < bestScore) {
                bestScore = score
                chosenMood = mood
                chosenTag = tag
                chosenSrc = candidateSrc
            }
        }
        usedSources.add(chosenSrc)
        usedTags.set(chosenTag, (usedTags.get(chosenTag) || 0) + 1)
        previousTag = chosenTag
        return chosenSrc
    })
}
