function splitThoughtIntoSix(text) {
    const raw = String(text || "").trim()
    const tokens = raw.split(/\s+/).filter(Boolean)
    if (!tokens.length) return Array.from({ length: 6 }, () => "THIS THOUGHT")
    if (tokens.length >= 6) {
        const out = Array.from({ length: 6 }, () => [])
        tokens.forEach((token, i) => {
            const bucket = Math.min(5, Math.floor((i * 6) / tokens.length))
            out[bucket].push(token)
        })
        return out.map((part, i) => part.join(" ") || tokens[i % tokens.length])
    }
    return Array.from({ length: 6 }, (_, i) => tokens[i % tokens.length] || raw)
}
