function releaseEmotionProfile(input) {
    {
        const eosProfile = EosProfileOverride(input)
        if (eosProfile) return eosProfile
    }
    const raw = Array.isArray(input) ? input.join(" ") : String(input || "")
    return (
        RELEASE_INPUT_EMOTION_PROFILES.find((p) => p.test.test(raw)) ||
        RELEASE_DEFAULT_EMOTION_PROFILE
    )
}
function releaseGestureForGame(game) {
    const a = `${game?.action || ""} ${game?.hook || ""}`.toLowerCase()
    if (Number(game?.id) >= 111) return { arrow: "", verb: ({ hold: "HOLD", holdRelease: "HOLD", drag: "DRAG", dragTo: "DRAG", slow: "DRAG", swipe: "SWIPE", sling: "PULL" })[EOS_GAME_META[Number(game.id)]?.gesture] || "TAP" }
    if (
        game?.id === 97 ||
        /drag[^.]*right|move[^.]*right|swipe[^.]*right|\bright\b/.test(a)
    )
        return { arrow: "→", verb: /swipe/.test(a) ? "SWIPE" : "DRAG" }
    if (
        game?.id === 101 ||
        /drag[^.]*left|pull[^.]*left|move[^.]*left|swipe[^.]*left|\bleft\b/.test(
            a
        )
    )
        return {
            arrow: "←",
            verb: /swipe/.test(a) ? "SWIPE" : /pull/.test(a) ? "PULL" : "DRAG",
        }
    if (/\bup\b|lift|raise/.test(a))
        return { arrow: "↑", verb: /lift|raise/.test(a) ? "LIFT" : "DRAG" }
    if (/apart|outward|away|throw|launch|flick/.test(a))
        return {
            arrow: "↗",
            verb: /throw|launch|flick/.test(a) ? "FLICK" : "DRAG",
        }
    if (/into|bin|target/.test(a)) return { arrow: "↘", verb: "DRAG" }
    if (game?.id === 105) return { arrow: "", verb: "TAP" }
    if (
        /drag[^.]*down|pull[^.]*down|\bdown\b|lower|drop|drain|lever|cloud/.test(
            a
        ) ||
        [98, 103, 110].includes(game?.id)
    )
        return {
            arrow: "↓",
            verb: /lower/.test(a) ? "LOWER" : /drag/.test(a) ? "DRAG" : "PULL",
        }
    if (/swipe/.test(a)) return { arrow: "↔", verb: "SWIPE" }
    if (/drag|move|slide|peel/.test(a)) return { arrow: "↔", verb: "DRAG" }
    const legacyArrow = Number(game?.id || 0) > 0 && Number(game?.id || 0) < 100
    if (/hold|press and hold|keep pressing/.test(a) || game?.id === 99)
        return { arrow: legacyArrow ? "↑" : "", verb: "HOLD" }
    if (/scratch/.test(a))
        return { arrow: legacyArrow ? "↗" : "", verb: "SCRATCH" }
    if (/shake/.test(a))
        return { arrow: legacyArrow ? "↔" : "", verb: "SHAKE" }
    if (/turn|rotate|knob|dial/.test(a))
        return { arrow: legacyArrow ? "↻" : "", verb: "TURN" }
    if (/stomp/.test(a)) return { arrow: legacyArrow ? "↓" : "", verb: "STOMP" }
    if (/tap|click|choose|select|press|pop|zap|burn/.test(a))
        return { arrow: legacyArrow ? "↑" : "", verb: "TAP" }
    if (/pull/.test(a)) return { arrow: legacyArrow ? "↔" : "", verb: "PULL" }
    return { arrow: legacyArrow ? "↑" : "", verb: "TAP" }
}
function dynamicReleaseActionCue(game, entries, index = 0) {
    const profile = releaseEmotionProfile(entries)
    const gesture = releaseGestureForGame(game)
    const offset = Math.abs((Number(game?.id) || 0) + Number(index || 0))
    const target = profile.actions[offset % profile.actions.length]
    return {
        ...gesture,
        target,
        label: `${gesture.verb} TO ${target}`,
        profile,
    }
}
