    const normaliseThought = (value) =>
        String(value || "")
            .toLowerCase()
            .replace(/[^\p{L}\p{N}\s']/gu, " ")
            .replace(/\s+/g, " ")
            .trim()
    const chooseRelevantGame = React.useCallback(
        (thought, excludeId = null, contextGame = null) => {
            const q = normaliseThought(thought)
            const tokens = new Set(q.split(" ").filter((x) => x.length > 2))
            const recent = new Set(played.slice(-6))
            const keywordBoost = {
                1: ["annoy", "little", "small", "pop", "irritat", "nag"],
                3: ["crack", "stuck", "sealed", "break", "pressure"],
                4: [
                    "angry",
                    "anger",
                    "mad",
                    "furious",
                    "rage",
                    "frustrat",
                    "stomp",
                ],
                6: ["buzz", "agitat", "angry", "energy", "zap", "irritat"],
                16: ["melt", "rigid", "tense", "hard", "frozen", "stiff"],
                15: [
                    "message",
                    "words",
                    "text",
                    "reread",
                    "shred",
                    "done with",
                ],
                22: [
                    "flush",
                    "drain",
                    "get rid",
                    "gross",
                    "sick of",
                    "circling",
                ],
                18: ["burn", "sentence", "done", "carrying", "resent", "anger"],
                25: ["away", "swipe", "reject", "dismiss", "leave", "move on"],
                23: [
                    "clutter",
                    "headspace",
                    "too much",
                    "overwhelm",
                    "mess",
                    "vacuum",
                ],
                24: ["distance", "far", "away", "space", "escape", "leave me"],
                19: [
                    "erase",
                    "memory",
                    "embarrass",
                    "shame",
                    "regret",
                    "wish i hadn't",
                ],
                41: [
                    "hooked",
                    "attached",
                    "can't let go",
                    "stuck on",
                    "obsess",
                    "keep thinking",
                ],
                71: [
                    "urgent",
                    "panic",
                    "alarm",
                    "countdown",
                    "anxious",
                    "anxiety",
                    "fear",
                ],
                61: [
                    "racing",
                    "fast",
                    "freeze",
                    "spiral",
                    "overthink",
                    "can't stop",
                ],
            }
            let best = GAMES[0]
            let bestScore = -999
            GAMES.forEach((g, index) => {
                if (excludeId != null && g.id === excludeId) return
                const hay = normaliseThought(
                    `${g.name} ${g.family} ${g.prompt} ${g.object} ${g.action} ${g.mechanism} ${g.hook} ${g.mindBend}`
                )
                let scoreForGame = 0
                tokens.forEach((token) => {
                    if (hay.includes(token)) scoreForGame += 1.1
                })
                ;(keywordBoost[g.id] || []).forEach((word) => {
                    if (q.includes(word)) scoreForGame += 4.25
                })
                if (
                    contextGame?.family === "Release" &&
                    normaliseThought(g.mechanism).includes("distanc")
                )
                    scoreForGame += 2.75
                const recentGames = played
                    .slice(-6)
                    .map((id) => GAMES.find((item) => item.id === id))
                    .filter(Boolean)
                const familyAffinity = recentGames.filter(
                    (item) => item.family === g.family
                ).length
                scoreForGame += familyAffinity * 0.12
                if (contextGame && g.family !== contextGame.family)
                    scoreForGame += 0.18
                if (recent.has(g.id)) scoreForGame -= 1.2
                scoreForGame += (GAMES.length - index) * 0.0005
                if (!played.includes(g.id)) scoreForGame += 0.18
                if (scoreForGame > bestScore) {
                    bestScore = scoreForGame
                    best = g
                }
            })
            return best || GAMES[0]
        },
        [played.join("|")]
    )
